-- Schema only. Performance indexes and partitions intentionally live in database-labs.
CREATE TABLE payment (id BIGSERIAL PRIMARY KEY, payment_key VARCHAR(128) NOT NULL UNIQUE, order_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL, provider VARCHAR(32) NOT NULL, amount NUMERIC(19,2) NOT NULL, currency VARCHAR(3) NOT NULL, status VARCHAR(32) NOT NULL, provider_transaction_id VARCHAR(128) NULL, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE payment_attempt (id BIGSERIAL PRIMARY KEY, payment_id BIGINT NOT NULL REFERENCES payment(id), attempt_no INT NOT NULL, request_json JSONB NULL, response_json JSONB NULL, outcome VARCHAR(32) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE refund (id BIGSERIAL PRIMARY KEY, refund_key VARCHAR(128) NOT NULL UNIQUE, payment_id BIGINT NOT NULL REFERENCES payment(id), amount NUMERIC(19,2) NOT NULL, status VARCHAR(32) NOT NULL, provider_refund_id VARCHAR(128) NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE payment_reconciliation_state (id BIGSERIAL PRIMARY KEY, payment_id BIGINT NOT NULL UNIQUE REFERENCES payment(id), retry_count INT NOT NULL DEFAULT 0, next_retry_at TIMESTAMP NULL, last_error TEXT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE inbox_event (id BIGSERIAL PRIMARY KEY, consumer_name VARCHAR(128) NOT NULL, event_id VARCHAR(36) NOT NULL, processed_at TIMESTAMP NOT NULL, UNIQUE(consumer_name,event_id));
CREATE TABLE outbox_event (id BIGSERIAL PRIMARY KEY, event_id VARCHAR(36) NOT NULL UNIQUE, aggregate_id VARCHAR(128) NOT NULL, event_type VARCHAR(128) NOT NULL, payload_json JSONB NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP NOT NULL, processed_at TIMESTAMP NULL);
